import re
import logging
from taf.selenium.sbts.facade import (Sbts,
                                      Sbts20B,
                                      Sbts21A,
                                      Sbts21B,
                                      Sbts22R1,
                                      Sbts22R2,
                                      Sbts22R3,
                                      Sbts22R4,
                                      Sbts23R1,
                                      Sbts23R2,
                                      Sbts23R3,
                                      Sbts23R4,
                                      Sbts24R1,
                                      Sbts24R2,
                                      Sbts24R3,
                                      Sbts25R1,
                                      Sbts25R2,
                                      Sbts25R3,
                                      Sbts26R1,
                                      Sbts26R2,
                                      Sbts26R3)


class SupportedSbts(object):
    sbts = Sbts
    sbts20b = Sbts20B
    sbts21a = Sbts21A
    sbts21b = Sbts21B
    sbts22r1 = Sbts22R1
    sbts22r2 = Sbts22R2
    sbts22r3 = Sbts22R3
    sbts22r4 = Sbts22R4
    sbts23r1 = Sbts23R1
    sbts23r2 = Sbts23R2
    sbts23r3 = Sbts23R3
    sbts23r4 = Sbts23R4
    sbts24r1 = Sbts24R1
    sbts24r2 = Sbts24R2
    sbts24r3 = Sbts24R3
    sbts25r1 = Sbts25R1
    sbts25r2 = Sbts25R2
    sbts25r3 = Sbts25R3
    sbts26r1 = Sbts26R1
    sbts26r2 = Sbts26R2
    sbts26r3 = Sbts26R3


class Provider(object):
    default_version = 'sbts26r3'

    @classmethod
    def provide(cls, version=None):
        if version == "" or version is None:
            supported_sbts = cls.default_version
        else:
            regex_for_version = "(?:[Ss][Bb][Tt][Ss])?(.*)?"
            version_parsed = re.search(regex_for_version, version).groups()[0]
            supported_sbts = "sbts{version}".format(version=version_parsed.lower())

        sbts_cls = getattr(SupportedSbts, supported_sbts, getattr(SupportedSbts, cls.default_version))
        logging.info("specified version {}, found supported {}, selected sbts {}".format(version,
                                                                                         supported_sbts,
                                                                                         sbts_cls))
        return sbts_cls
